//! The protected-listing judge (`owbuy.rs`, docs/v8/ow-protected.md §3.1) held to Ordinals Wallet's own vectors
//! (`tests/fixtures/ow/`, MIT, generated by its SDK from throwaway keys).
//!
//! Every sale, setup and single-item purchase case is run through the canister's judge with the fixture's buyer standing in for
//! the float. Custody is taken two ways:
//!
//! - **literally**: custody is the fixture's recipient, or its buyer when it names none. The fixtures send the item to the
//!   buyer's own address, so custody is the float's script, and the canister's P7 (exactly one custody output, told apart from
//!   change) refuses every such case with `CustodyIsFloat`. That is asserted, case by case.
//! - **as the canister builds**: the runner asks Ordinals Wallet to build with `to` = custody, a script distinct from the
//!   float's. The fixture is rewritten the way that build would differ: the output the escrow's first sat lands on, when it pays
//!   the recipient, pays custody instead (same length, nothing else moves). Every rule then gets to speak, and each case must be
//!   decided as the SDK decides it, or refused by a canister-stricter rule listed below by name with its reason.
//!
//! The located-inscription facts the canister would read from ord are derived from the fixture: the inscription's output is
//! the listing's `outpoint` (the fixtures carry no separate `source_outpoint`), its value is the parent's output value plus
//! `d` = 0 (every fixture parent is 546 → 546), and its offset is 0. The cap is a generous 10,000,000 sats unless the purchase
//! states `max_total_sat`, which is exactly the canister's cap: the SDK's `total_sat` and the canister's `spend` (the float's
//! inputs less its outputs) are the same number.

use etch_autobuyer::custody::Outpoint;
use etch_autobuyer::frogbuy::{fee_bound, Seller};
use etch_autobuyer::owbuy::{judge_protected, judge_setup, Judged, Listing, ProtectedFacts, Refused, COSIGNER, MARKET_FEE_ADDRESS};
use etch_autobuyer::policy::{script_of, taproot_address};
use etch_autobuyer::psbt::{parse_raw_tx, Psbt};
use etch_autobuyer::taptree::{self, NUMS, TAPSCRIPT};
use serde_json::Value;

const CUSTODY: [u8; 34] = {
    let mut s = [0xcc; 34];
    s[0] = 0x51;
    s[1] = 0x20;
    s
};
const GENEROUS_CAP: u64 = 10_000_000;

fn fixture(name: &str) -> Value {
    let text = match name {
        "purchase" => include_str!("fixtures/ow/purchase-verify.json"),
        _ => include_str!("fixtures/ow/escrow.json"),
    };
    serde_json::from_str(text).unwrap()
}
/// Hex, or the text's own bytes when it is not hex (the "garbage" cases).
fn bytes(v: &Value) -> Vec<u8> {
    let s = v.as_str().unwrap_or("");
    hex::decode(s).unwrap_or_else(|_| s.as_bytes().to_vec())
}
fn addr(a: &str) -> Vec<u8> {
    script_of(a, "bc").unwrap()
}
fn h32(s: &str) -> [u8; 32] {
    hex::decode(s).unwrap().try_into().unwrap()
}
/// A refusal's variant name.
fn name(r: &Refused) -> String {
    match r {
        Refused::InSetup(inner) => format!("InSetup({})", name(inner)),
        r => format!("{r:?}").split(|c: char| !c.is_alphanumeric()).next().unwrap().to_string(),
    }
}

/// Offsets of output `j`'s value and script inside a PSBT's unsigned transaction.
fn output_offsets(p: &[u8], j: usize) -> (usize, usize) {
    fn compact(b: &[u8], i: &mut usize) -> usize {
        let f = b[*i];
        *i += 1;
        match f {
            0..=0xfc => f as usize,
            0xfd => {
                let v = u16::from_le_bytes([b[*i], b[*i + 1]]) as usize;
                *i += 2;
                v
            }
            _ => panic!("no fixture transaction is that large"),
        }
    }
    let mut i = 5;
    assert_eq!((p[i], p[i + 1]), (1, 0), "the unsigned transaction is the global map's first pair");
    i += 2;
    compact(p, &mut i);
    i += 4;
    let n_in = compact(p, &mut i);
    for _ in 0..n_in {
        i += 36;
        let l = compact(p, &mut i);
        i += l + 4;
    }
    assert!(j < compact(p, &mut i));
    for _ in 0..j {
        i += 8;
        let l = compact(p, &mut i);
        i += l;
    }
    let value_at = i;
    i += 8;
    assert_eq!(compact(p, &mut i), 34);
    (value_at, i)
}

struct Case {
    sale: Vec<u8>,
    parent: Vec<u8>,
    listing: Listing,
    float: Vec<u8>,
    recipient: Vec<u8>,
    cap: u64,
    setup: Option<Vec<u8>>,
    /// Protected-listing review P-01: the creators pinned in the install's config. Here the fixture's creator, as an install for
    /// that collection would pin it (the listing's own `creator_address` is not read).
    creators: Vec<Vec<u8>>,
    /// Review P-02: the canister's fee rate, here the fixture's (none when it is 0: the canister never reads a zero rate).
    fee_rate: Option<u64>,
}

fn case(input: &Value, link: &Value) -> Case {
    let l = &link["listing"];
    let buyer = input["buyer_address"].as_str().unwrap();
    Case {
        sale: bytes(&link["sale_psbt"]),
        parent: bytes(&link["parent"]["raw"]),
        listing: Listing {
            outpoint: Outpoint::parse(l["outpoint"].as_str().unwrap()).unwrap(),
            seller_address: l["seller_address"].as_str().unwrap().into(),
            satoshi_price: l["satoshi_price"].as_u64().unwrap_or(0),
            escrow_price: l["escrow_price_sat"].as_u64(),
            creator_address: l["creator_address"].as_str().map(String::from),
        },
        float: addr(buyer),
        recipient: addr(input["recipient_address"].as_str().unwrap_or(buyer)),
        cap: input["max_total_sat"].as_u64().unwrap_or(GENEROUS_CAP),
        setup: input.get("setup").filter(|s| !s.is_null()).map(|s| bytes(&s["psbt"])),
        creators: l["creator_address"].as_str().map(addr).into_iter().collect(),
        fee_rate: input["fee_rate"].as_u64().filter(|r| *r > 0),
    }
}

impl Case {
    /// ord's reading, as the fixture implies it (see the module comment).
    fn located(&self) -> Seller {
        let value = parse_raw_tx(&self.parent).ok().and_then(|p| p.tx.outputs.first().map(|o| o.value)).unwrap_or(546);
        Seller { outpoint: self.listing.outpoint, offset: 0, value }
    }
    fn judge(&self, sale: &[u8], custody: &[u8]) -> Result<Judged, Refused> {
        let f = ProtectedFacts { float: &self.float, custody, inscription: self.located(), cap_sats: self.cap, creators: &self.creators,
            fee_rate: self.fee_rate };
        judge_protected(sale, &self.parent, &self.listing, &f, self.setup.as_deref())
    }
    fn literal(&self) -> Result<Judged, Refused> {
        self.judge(&self.sale, &self.recipient)
    }
    /// The sale as a build with `to` = custody would be: the output holding the escrow's first sat, when it pays the recipient,
    /// pays custody.
    fn built_to_custody(&self) -> Vec<u8> {
        let mut sale = self.sale.clone();
        let (Ok(p), Ok(parent)) = (Psbt::parse(&sale), parse_raw_tx(&self.parent)) else { return sale };
        let mut internal = parent.txid;
        internal.reverse();
        let Some(k) = p.tx.inputs.iter().position(|i| i.txid == internal) else { return sale };
        let Some(start) = p.witness_utxos[..k].iter().map(|u| u.as_ref().map(|u| u.value)).sum::<Option<u64>>() else { return sale };
        let mut s = 0u64;
        for (j, o) in p.tx.outputs.iter().enumerate() {
            if start >= s && start - s < o.value {
                if o.script == self.recipient {
                    let (_, at) = output_offsets(&sale, j);
                    sale[at..at + 34].copy_from_slice(&CUSTODY);
                }
                break;
            }
            s += o.value;
        }
        sale
    }
    fn to_custody(&self) -> Result<Judged, Refused> {
        self.judge(&self.built_to_custody(), &CUSTODY)
    }
}

/// The SDK's refusal codes, and the canister variants that are the same rule.
fn same_rule(code: &str) -> &'static [&'static str] {
    match code {
        "sale_payout_mismatch" => &["NoPayout", "PayoutPrice"],
        "sale_asset_mismatch" => &["NotToCustody", "CustodyValue", "CustodyOutputs"],
        "sale_leaf_unpinned" => &["LeafUnpinned"],
        "sale_escrow_mismatch" => &["EscrowScript"],
        "sale_template_internal_key" => &["EscrowInternalKey"],
        "sale_not_cosigned" => &["EscrowNotCosignable"],
        "sale_witness_sighash" | "sale_witness_shape" => &["EscrowWitness"],
        "parent_source_mismatch" => &["ParentSource", "ParentShape"],
        "sale_prevout_mismatch" => &["EscrowPrevout"],
        "sale_unknown_output" => &["UnknownOutput", "OpReturn"],
        "sale_change_mismatch" => &["ChangeFirst"],
        "sale_fee" => &["FeeTooHigh", "NoNetworkFee", "FeeRateTooHigh"],
        "buyer_sighash" => &["Sighash", "InSetup(Sighash)"],
        "funding_not_yours" => &["ForeignInput"],
        "funding_prefilled" => &["InputSigned", "InSetup(InputSigned)"],
        "sale_input_count" => &["InputLayout"],
        "invalid_psbt" | "invalid_parent" => &["Unparsable"],
        // review P-01: the fee is bounded on the seller's own price, not the API's satoshi_price
        "sale_overcharge" => &["MarketFee"],
        "sale_royalty" => &["Royalty"],
        "listing_price_unknown" => &["NoPrice"],
        "over_budget" | "invalid_budget" => &["OverCap"],
        "chain_funding_mismatch" => &["NotFundedBySetup"],
        "setup_output_not_yours" => &["SetupOutputNotFloat"],
        "setup_output_shape" => &["SetupOutputs"],
        "setup_input_not_yours" => &["InSetup(ForeignInput)"],
        "setup_fee" => &["InSetup(NoNetworkFee)", "FeeTooHigh"],
        other => panic!("an SDK code this test does not map: {other}"),
    }
}

/// Cases the canister decides differently from the SDK, built to custody. Each is (description, the canister's decision, why).
/// `Some(variant)`: refused by a canister-stricter rule. `None`: accepted although the SDK refuses, because the SDK's rule reads
/// an input the canister never takes.
const DIFFERENT: &[(&str, Option<&str>, &str)] = &[
    // stricter
    ("unknown escrow price, lower payout", Some("EscrowPriceUnknown"),
        "the canister pays exactly the seller's escrow_price or nothing; the SDK checks the payout only when it knows the price"),
    ("charges more than the listed price", Some("EscrowPriceUnknown"),
        "this listing has no escrow_price either; the SDK's overcharge is still caught by the canister had it one (see the inflated-fee case)"),
    ("with setup", Some("NotFundedBySetup"),
        "the fixture's sale states setup:1 at 20,000 sats while the setup's output 1 is 99,100: the canister checks each funding \
         input's value and script against the setup (BIP 341 commits to them, so this sale could never confirm); the SDK checks \
         only the outpoint. Its fees (1,900 sats on a 53,750-sat spend, 3.5%) are also over fee_bound (1,612)"),
    ("setup misdeclares its txid", Some("NotFundedBySetup"),
        "the same sale as \"with setup\", refused for the same misstated value before any txid is compared"),
    ("funding input asking for SIGHASH_ALL", Some("Sighash"),
        "the canister signs only SIGHASH_DEFAULT (64-byte signatures, what the SDK's own signer produces): a PSBT asking for ALL \
         is refused rather than signed with another type"),
    // inputs the canister does not take
    ("passthrough not hashing to its txid", None,
        "only the declared parent txid is wrong (dddd…); the canister takes no declared txid: the parent is the transaction \
         whose raw bytes hash to the txid the sale's escrow input spends, which these do"),
    ("sale not hashing to its declared txid", None,
        "only the declared sale txid is wrong; the canister computes the txid it will watch from the unsigned transaction"),
    ("expired quote", None, "the canister reads no quote expiry: a handed sale goes stale on the canister's own clock (§3.3)"),
    ("quote expiring exactly now", None, "as above"),
    ("unreadable expiry", None, "as above"),
    ("zero fee rate", None, "the canister takes no fee rate: its fee bound is frogbuy::fee_bound(spend)"),
];

/// Multi-item purchases: the canister buys one item per buy (design §5), so a chain is never handed to it.
fn single_item(c: &Value) -> Option<&Value> {
    let links = c["input"]["links"].as_array().unwrap();
    (links.len() == 1).then(|| &links[0])
}

fn check(desc: &str, sdk: &Value, got: &Result<Judged, Refused>) {
    let code = sdk["code"].as_str();
    if let Some((_, decision, why)) = DIFFERENT.iter().find(|(d, ..)| *d == desc) {
        match (decision, got) {
            (Some(v), Err(r)) => assert_eq!(name(r), *v, "{desc}: {why}"),
            (None, Ok(_)) => {}
            _ => panic!("{desc}: expected {decision:?} ({why}), got {got:?}"),
        }
        return;
    }
    match (code, got) {
        (None, Ok(j)) => {
            assert_eq!(j.escrow_input as u64, sdk["passthrough_input"].as_u64().unwrap(), "{desc}");
            let buyer: Vec<usize> = sdk["buyer_inputs"].as_array().unwrap().iter().map(|v| v.as_u64().unwrap() as usize).collect();
            assert_eq!(j.float_inputs, buyer, "{desc}");
            assert_eq!(j.custody_vout as u64, sdk["asset_output"].as_u64().unwrap(), "{desc}");
            assert_eq!(j.sale_fee, sdk["network_fee_sat"].as_u64().unwrap(), "{desc}");
            assert_eq!(j.seller_payout, sdk["seller_proceeds_sat"].as_u64().unwrap(), "{desc}");
            assert_eq!(j.market_fee, sdk["market_fee_sat"].as_u64().unwrap(), "{desc}");
            assert_eq!(j.royalty, sdk["creator_royalty_sat"].as_u64().unwrap(), "{desc}");
            assert!(j.fee <= fee_bound(j.spend), "{desc}");
        }
        (None, Err(r)) => panic!("{desc}: the SDK accepts, the canister refuses with {r:?} and no stricter rule is listed"),
        (Some(code), Ok(_)) => panic!("{desc}: the SDK refuses ({code}), the canister accepts"),
        (Some(code), Err(r)) => assert!(same_rule(code).contains(&name(r).as_str()), "{desc}: SDK {code}, canister {r:?}"),
    }
}

/// The per-link expectation of a purchase: its one link's derived numbers, or its refusal.
fn purchase_expect(c: &Value) -> Value {
    let e = &c["expect"];
    if e["ok"].as_bool() == Some(true) { e["links"][0].clone() } else { e.clone() }
}

#[test]
fn every_sale_is_decided_as_the_sdk_decides_or_by_a_named_stricter_rule() {
    let d = fixture("purchase");
    let sales = d["sales"].as_array().unwrap();
    assert_eq!(sales.len(), 36);
    for c in sales {
        let desc = c["description"].as_str().unwrap();
        check(desc, &c["expect"], &case(&c["input"], &c["input"]).to_custody());
    }
}

#[test]
fn every_single_item_purchase_is_decided_as_the_sdk_decides_or_by_a_named_stricter_rule() {
    let d = fixture("purchase");
    let (mut judged, mut chains) = (0, Vec::new());
    for c in d["purchases"].as_array().unwrap() {
        let desc = c["description"].as_str().unwrap();
        let Some(link) = single_item(c) else {
            chains.push(desc);
            continue;
        };
        check(desc, &purchase_expect(c), &case(&c["input"], link).to_custody());
        judged += 1;
    }
    assert_eq!(judged, 21);
    // never judged: the canister buys one item at a time, so there is no chain to hand it
    assert_eq!(
        chains,
        ["two chained items", "broken chain", "same listing twice", "chain spends the previous item output",
         "chain spends the previous payout output", "no items", "thirteen items"]
    );
}

/// Taken literally (custody = the fixture's recipient, which is the buyer unless named), the canister refuses every case the
/// SDK accepts: custody would be the float, and P7 cannot tell custody's output from change. Where the recipient is the listing's
/// creator, the royalty output pays custody too: two custody outputs. Every case the SDK refuses stays refused.
#[test]
fn taken_literally_custody_is_the_buyer_and_the_canister_refuses_it() {
    let d = fixture("purchase");
    let mut runs: Vec<(String, Value, Case)> = Vec::new();
    for c in d["sales"].as_array().unwrap() {
        runs.push((c["description"].as_str().unwrap().into(), c["expect"].clone(), case(&c["input"], &c["input"])));
    }
    for c in d["purchases"].as_array().unwrap() {
        if let Some(link) = single_item(c) {
            runs.push((c["description"].as_str().unwrap().into(), purchase_expect(c), case(&c["input"], link)));
        }
    }
    for (desc, sdk, k) in &runs {
        let got = k.literal();
        let Err(r) = &got else {
            // the declared-txid and quote cases are refused here too: custody is the float
            panic!("{desc}: accepted with custody = the buyer");
        };
        let n = name(r);
        match sdk["code"].as_str() {
            None if desc == "item delivered to the recipient" => assert_eq!(*r, Refused::CustodyOutputs(2), "{desc}"),
            None if desc == "unknown escrow price, lower payout" => assert_eq!(n, "EscrowPriceUnknown"),
            None if desc == "funding input asking for SIGHASH_ALL" => assert_eq!(n, "Sighash"),
            None => assert_eq!(*r, Refused::CustodyIsFloat, "{desc}"),
            // a case listed in DIFFERENT for an input the canister does not take: refused here anyway, custody being the float
            Some(_) if DIFFERENT.iter().any(|(d, ..)| d == desc) => {
                assert!(["CustodyIsFloat", "NotFundedBySetup", "EscrowPriceUnknown"].contains(&n.as_str()), "{desc}: {r:?}")
            }
            Some(code) => {
                let stricter = ["CustodyIsFloat", "CustodyOutputs", "EscrowPriceUnknown"];
                assert!(same_rule(code).contains(&n.as_str()) || stricter.contains(&n.as_str()), "{desc}: SDK {code}, canister {r:?}");
            }
        }
    }
}

#[test]
fn every_setup_is_decided_as_the_sdk_decides() {
    let d = fixture("purchase");
    let with_setup = d["purchases"].as_array().unwrap().iter().find(|c| c["description"] == "with setup").unwrap();
    for c in d["setups"].as_array().unwrap() {
        let desc = c["description"].as_str().unwrap();
        let float = addr(c["buyer_address"].as_str().unwrap());
        let got = judge_setup(&bytes(&c["psbt"]), &float);
        let e = &c["expect"];
        match (e["code"].as_str(), &got) {
            (None, Ok(s)) => {
                assert_eq!(hex::encode(s.txid), e["txid"].as_str().unwrap(), "{desc}");
                assert_eq!(s.fee, e["fee_sat"].as_u64().unwrap(), "{desc}");
                assert_eq!(s.float_inputs, vec![0], "{desc}");
            }
            // The SDK bounds a setup's fee by a fee rate the canister does not take. The canister bounds it together with the
            // sale's, by fee_bound of the whole spend, which only judge_protected knows (P9, P10). Standalone it is accepted;
            // handed in with a sale, the 40,000-sat fee alone is over any bound below 1.33M sats of spend.
            (Some("setup_fee"), Ok(s)) if desc == "fee far above the rate" || desc == "fee above a fractional rate" => {
                assert!(s.fee == 40_000 || s.fee == 500, "{desc}");
                let mut k = case(&with_setup["input"], &with_setup["input"]["links"][0]);
                k.setup = Some(bytes(&c["psbt"]));
                assert!(k.to_custody().is_err(), "{desc}: refused once judged with a sale");
            }
            (Some(code), Err(r)) => assert!(same_rule(code).contains(&name(r).as_str()), "{desc}: SDK {code}, canister {r:?}"),
            (code, got) => panic!("{desc}: SDK {code:?}, canister {got:?}"),
        }
    }
}

/// The txids the canister computes are the SDK's: the sale's from its unsigned transaction, the parent's from its raw bytes
/// (witness stripped, as for the seller-signed parent).
#[test]
fn the_txids_are_the_sdks() {
    let d = fixture("purchase");
    for c in d["sales"].as_array().unwrap() {
        let (desc, e, i) = (c["description"].as_str().unwrap(), &c["expect"], &c["input"]);
        if e["ok"].as_bool() == Some(true) {
            let p = Psbt::parse(&bytes(&i["sale_psbt"])).unwrap();
            assert_eq!(hex::encode(p.txid()), e["sale_txid"].as_str().unwrap(), "{desc}");
        }
        if let Ok(parent) = parse_raw_tx(&bytes(&i["parent"]["raw"])) {
            let declared = i["parent"]["txid"].as_str().unwrap();
            assert_eq!(hex::encode(parent.txid) == declared, desc != "passthrough not hashing to its txid", "{desc}");
        }
    }
    let seller_signed = d["sales"].as_array().unwrap().iter().find(|c| c["description"] == "seller-signed parent").unwrap();
    let raw = parse_raw_tx(&bytes(&seller_signed["input"]["parent"]["raw"])).unwrap();
    assert!(!raw.witnesses[0].is_empty(), "the seller-signed parent is the segwit serialisation");
}

#[test]
fn the_cap_and_the_fee_bound_are_the_canisters_own() {
    let d = fixture("purchase");
    let honest = &d["sales"][0];
    assert_eq!(honest["description"], "honest sale");
    let mut k = case(&honest["input"], &honest["input"]);
    // spend 52,850 (50,000 + 1,350 + 500 + 1,000): the cap binds at exactly that
    k.cap = 52_850;
    assert_eq!(k.to_custody().unwrap().spend, 52_850);
    k.cap = 52_849;
    assert_eq!(k.to_custody().unwrap_err(), Refused::OverCap { spend: 52_850, cap: 52_849 });
    k.cap = GENEROUS_CAP;
    // the miner fee: take sats off the last change output (5) and they go to the miner, raising spend and fee together
    let with_fee = |extra: u64| {
        let mut s = k.built_to_custody();
        let (at, _) = output_offsets(&s, 5);
        let v = u64::from_le_bytes(s[at..at + 8].try_into().unwrap()) - extra;
        s[at..at + 8].copy_from_slice(&v.to_le_bytes());
        k.judge(&s, &CUSTODY)
    };
    // 1,600 on 53,450 is under fee_bound (1,603); 1,700 on 53,550 is over it (1,606)
    assert_eq!(with_fee(600).unwrap().fee, 1_600);
    assert_eq!(with_fee(700).unwrap_err(), Refused::FeeTooHigh { fee: 1_700, bound: 1_606 });
}

#[test]
fn the_escrow_is_rebuilt_exactly_as_ordinals_wallet_builds_it() {
    let e = fixture("escrow");
    assert_eq!(h32(e["cosigner_x_only"].as_str().unwrap()), COSIGNER);
    assert_eq!(h32(e["nums_internal_key"].as_str().unwrap()), NUMS);
    assert_eq!(e["market_fee_address"], MARKET_FEE_ADDRESS);
    let protected = e["protected"].as_array().unwrap();
    assert_eq!(protected.len(), 5);
    for v in protected {
        let s = h32(v["seller_x_only"].as_str().unwrap());
        let esc = taptree::passthrough_escrow(&s, &COSIGNER).unwrap();
        assert_eq!(hex::encode(&esc.sale_leaf), v["leaf"].as_str().unwrap());
        assert_eq!(hex::encode(&esc.recovery_leaf), v["recovery_leaf"].as_str().unwrap());
        assert_eq!(hex::encode(&esc.script), v["script"].as_str().unwrap());
        assert_eq!(hex::encode(&esc.sale_control_block), v["leaf_control_block"].as_str().unwrap());
        assert_eq!(hex::encode(&esc.recovery_control_block), v["recovery_control_block"].as_str().unwrap());
        assert_eq!(hex::encode(taptree::leaf_hash(&esc.sale_leaf, TAPSCRIPT)), v["leaf_hash"].as_str().unwrap());
        let key: [u8; 32] = esc.script[2..].try_into().unwrap();
        assert_eq!(taproot_address(&key, "bc"), v["address"].as_str().unwrap());
    }
    for v in e["protected_errors"].as_array().unwrap() {
        let raw = hex::decode(v["seller_x_only"].as_str().unwrap()).unwrap();
        match <[u8; 32]>::try_from(raw.as_slice()) {
            Ok(s) => assert!(taptree::passthrough_escrow(&s, &COSIGNER).is_err(), "{}", v["description"]),
            Err(_) => assert_ne!(raw.len(), 32, "a key that is not 32 bytes cannot be named at all"),
        }
    }
    for v in e["passthrough_leaf_parse"].as_array().unwrap() {
        let got = taptree::parse_sale_leaf(&hex::decode(v["leaf"].as_str().unwrap()).unwrap());
        let want = v["keys"].as_object().map(|k| (h32(k["seller"].as_str().unwrap()), h32(k["cosigner"].as_str().unwrap())));
        assert_eq!(got, want, "{}", v["description"]);
    }
    // the generic two-leaf tree against the offer escrows too (other recovery leaves, the same NUMS)
    let offers = e["offer"].as_array().unwrap();
    assert_eq!(offers.len(), 23);
    for v in offers {
        let t = taptree::two_leaf(&NUMS, &hex::decode(v["sale_leaf"].as_str().unwrap()).unwrap(),
            &hex::decode(v["recovery_leaf"].as_str().unwrap()).unwrap()).unwrap();
        assert_eq!(hex::encode(&t.script), v["script"].as_str().unwrap());
        assert_eq!(taproot_address(&t.output_key, "bc"), v["address"].as_str().unwrap());
    }
}
